      "id": "modern-c03-l11-p02-001",
      "title": "欧州側の呼称「暗黒大陸」への批判",
      "body": [
        "分割以前のアフリカを、ヨーロッパ人たちは<strong class=\"source-bold\">文明のない未開の地</strong>という意味で、<strong class=\"source-bold\">「暗黒大陸」</strong>って呼んでたんだよ。これって、キリスト教じゃないから暗黒……みたいな、むちゃくちゃ上から目線の呼び方だな。"
      ],
