        "分割以前のアフリカを、ヨーロッパ人たちは文明のない未開の地という意味で、「暗黒大陸」って呼んでたんだよ。これって、キリスト教じゃないから暗黒……みたいな、むちゃくちゃ上から目線の呼び方だな。"
