      "title": "リヴィングストンの探検と行方不明",
      "body": [
        "このうち、アフリカ東部や南部の探検をしたのが<strong class=\"source-bold\">イギリス人<ruby>宣教師<rt>せんきょうし</rt></ruby></strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リヴィングストン</strong></span>だ。彼は探検をしながらキリスト教を<ruby>布教<rt>ふきょう</rt></ruby>し、さらにムスリム商人がやっている<ruby>奴隷<rt>どれい</rt></ruby>貿易を根絶しようとしたんだよ。そして、南アフリカの奥地で大きな滝（<strong class=\"source-bold\">ヴィクトリア<ruby>瀑布<rt>ばくふ</rt></ruby></strong>って名前になった）を見つけたあとに、あの<strong class=\"source-bold\">広大なアフリカ大陸で行方不明</strong>。こりゃー大事だ！"
      ],
