      "title": "1884〜85年のベルリン＝コンゴ会議",
      "body": [
        "イギリスがマフディー軍の鎮圧に手こずっているころ、<strong class=\"source-bold\">アフリカをめぐる状況は大きく変わった</strong>よ。それが、1884〜85年に<strong class=\"source-bold\">コンゴ問題</strong>に関して開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会</strong></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">議</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン=コンゴ会議</strong></span>】だ。"
      ],
      "plainBody": [
        "イギリスがマフディー軍の鎮圧に手こずっているころ、アフリカをめぐる状況は大きく変わったよ。それが、1884〜85年にコンゴ問題に関して開かれたベルリン会議【ベルリン=コンゴ会議】だ。"
      ],
