      "id": "modern-c03-l11-p02-030",
      "title": "コンゴ問題を利用したビスマルクの外交",
      "body": [
        "ビスマルクはコンゴ問題をうまいこと利用した。独仏の連携をちらつかせてイギリスの譲歩を引き出し、フランスを対外進出に向かわせてドイツの安全を図り、さらに列強の勢力均衡を図りながら、<strong class=\"source-bold\">ドイツもアフリカ進出の機会を狙い</strong>、最終的に<strong class=\"source-bold\">ドイツを中心とする大国の国際関係をつくる</strong>。ビスマルクは策略家だな。"
      ],
      "plainBody": [
        "ビスマルクはコンゴ問題をうまいこと利用した。独仏の連携をちらつかせてイギリスの譲歩を引き出し、フランスを対外進出に向かわせてドイツの安全を図り、さらに列強の勢力均衡を図りながら、ドイツもアフリカ進出の機会を狙い、最終的にドイツを中心とする大国の国際関係をつくる。ビスマルクは策略家だな。"
      ],
