      "id": "modern-c03-l11-p02-036",
      "title": "アルジェリア・チュニジアと横断政策",
      "body": [
        "<strong class=\"source-bold\">フランス</strong>は1830年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シャルル10世</strong></span>が出兵して、すでに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア</strong></span>を領有し、さらに、1878年の<strong class=\"source-bold\">ベルリン会議</strong>（これは<strong class=\"source-bold\">東方問題をめぐるベルリン会議</strong>ね）で優先権を認められた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チュニジア</strong></span>を保護国にしていたんだけど、ベルリン=コンゴ会議のあと、「早い者勝ちなら、イギリスに取られる前にアフリカをどんどん取ってしまえ！」って思って、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ横断政策</strong></span>を進めたよ。"
      ],
      "plainBody": [
        "フランスは1830年にシャルル10世が出兵して、すでにアルジェリアを領有し、さらに、1878年のベルリン会議（これは東方問題をめぐるベルリン会議ね）で優先権を認められたチュニジアを保護国にしていたんだけど、ベルリン=コンゴ会議のあと、「早い者勝ちなら、イギリスに取られる前にアフリカをどんどん取ってしまえ！」って思って、アフリカ横断政策を進めたよ。"
      ],
