      "title": "ナタール征服とブール人の内陸移住",
      "body": [
        "ただ、インドへの航路を確保したいイギリスは、ブール人が海岸沿いにいるのは気に食わない。<strong class=\"source-bold\">ナタール共和国はすぐにイギリスに征服されて</strong>しまい、ブール人はさらに内陸に移住して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トランスヴァール共和国</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オレンジ自由国</strong></span>を建てたよ。"
      ],
