      "id": "modern-c03-l11-p03-014",
      "title": "長引いた戦争と莫大な犠牲・戦費",
      "body": [
        "戦争は3年弱も続き、<strong class=\"source-bold\">苦戦したイギリス</strong>は45万人もの兵士を南アフリカに送ることになった。しかも戦死者は2万人以上！。しかも、イギリスが使った戦費は2億ポンド以上（これって、当時の年間税収の約3倍だよ！）。これだけの人とお金を使ってなんとか<strong class=\"source-bold\">トランスヴァールとオレンジを併合</strong>したけど、この戦争のあと、イギリスは外交戦略を見直す必要に迫られたんだよ。"
      ],
      "plainBody": [
        "戦争は3年弱も続き、苦戦したイギリスは45万人もの兵士を南アフリカに送ることになった。しかも戦死者は2万人以上！。しかも、イギリスが使った戦費は2億ポンド以上（これって、当時の年間税収の約3倍だよ！）。これだけの人とお金を使ってなんとかトランスヴァールとオレンジを併合したけど、この戦争のあと、イギリスは外交戦略を見直す必要に迫られたんだよ。"
      ],
