      "id": "modern-c03-l11-p03-017",
      "title": "白人政権と人種隔離への批判",
      "body": [
        "トランスヴァールの一部の軍人たちが、自分たちの自治権を回復するためにイギリスに協力し、<strong class=\"source-bold\">イギリスもブール人を味方にするために</strong>、「同じ白人同士なんだから、<strong class=\"source-bold\">黒人を<ruby>弾圧<rt>だんあつ</rt></ruby>して仲良くやりましょう</strong>」って、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アパルトヘイト</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人種<ruby>隔離<rt>かくり</rt></ruby>政策</strong></span>）を始めた。ひどい話だな。1991年まで続く黒人への人種隔離政策は、こんなふうにイギリスが始めたんだよ。"
      ],
      "plainBody": [
        "トランスヴァールの一部の軍人たちが、自分たちの自治権を回復するためにイギリスに協力し、イギリスもブール人を味方にするために、「同じ白人同士なんだから、黒人を弾圧して仲良くやりましょう」って、アパルトヘイト（人種隔離政策）を始めた。ひどい話だな。1991年まで続く黒人への人種隔離政策は、こんなふうにイギリスが始めたんだよ。"
      ],
