      "title": "ベルベル人の反乱とアガディールへの軍艦派遣",
      "body": [
        "それでもヴィルヘルム2世は諦めなかった。1911年、<strong class=\"source-bold\">モロッコ</strong>でフランスに対する<strong class=\"source-bold\">ベルベル人の反乱</strong>が起きると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>は突然、<strong class=\"source-bold\">軍艦をモロッコの</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アガディール</strong></span><strong class=\"source-bold\">に派遣した</strong>んだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次モロッコ事件</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アガディール事件</strong></span>】だよ。"
      ],
