export const sourcePages = {
  "199": "<h2>199</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">第3章</strong></span></h1>\n<h1><span data-source-color=\"white\" data-source-background=\"pink\" style=\"color:#ffffff;background-color:#f0a0a0\"><strong class=\"source-bold\">帝国主義と第一次世界大戦</strong></span></h1>",
  "200": "<h2>200</h2>\n<h1><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> <span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">帝国主義とアフリカ分割</strong></span></h1>\n<p>それじゃあ、またヨーロッパ諸国の動向を見ていくよ。産業革命が進んだヨーロッパ諸国は、いよいよ次の段階である<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">帝国主義の時代</strong></u>に突入するんだ。そして、<ruby>列強<rt>れっきょう</rt></ruby>の対立は、ヨーロッパのなかだけじゃなくて世界各地で繰り広げられることになるよ。その標的となったのがアジアやアフリカだ。今回は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アフリカ分割</strong></u>だよ。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">大きくつかもう！</strong></span></h3>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td><td></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span></td><td><strong class=\"source-bold\">第2次産業革命と帝国主義</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">201〜202ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span></td><td><strong class=\"source-bold\">アフリカ分割①（北部・東部・西部）</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">203〜209ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span></td><td><strong class=\"source-bold\">アフリカ分割②（南アフリカ）</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">209〜211ページ</span></td></tr><tr><td><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span></td><td><strong class=\"source-bold\">ドイツの「世界政策」とモロッコ事件</strong></td><td><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\">211〜214ページ</span></td></tr></tbody></table></div>\n<p><span data-source-marker=\"arrow\" style=\"color:#e52715\">↓</span><br><span data-source-marker=\"arrow\" style=\"color:#e52715\">↓</span><br><span data-source-marker=\"arrow\" style=\"color:#e52715\">↓</span><br><span data-source-marker=\"arrow\" style=\"color:#e52715\">↓</span></p>\n<blockquote><p>20世紀に入った時、アフリカはほとんどが列強の植民地になっていたんだ</p></blockquote>\n<p>19世紀前半にはヨーロッパ各国で<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">産業革命</strong></u>が始まって、列強は<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">工業製品の輸出を拡大したい</strong></u>とか、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">原料を安く確保したい</strong></u>などの理由で世界各地に進出したけど、工業の発展とともに進出の仕方が変わってきて、いよいよ<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">世界各地を分割し始める</strong></u>んだよ。アジア各国の植民地化はすでに前章で見たけど、列強が最も激しく分割を争ったのは<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">アフリカ</strong></u>だ。20世紀に入った時、アフリカにはほとんど独立国は残っていなかった！。 そして、アフリカをめぐる問題は、<u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\"><strong class=\"source-bold\">列強の対立をさらに激しくさせた</strong></u>んだよ。</p>\n<p>それじゃあ、アフリカ分割の始まりだ〜。</p>",
  "201": "<h2>201</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">第2次産業革命と帝国主義</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">1</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">第2次産業革命と帝国主義</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">産業革命にも段階があるよ。第2次産業革命って何？</strong></span></h4>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第6回</strong></span>の文化史のところでも少し話したけど、<strong class=\"source-bold\">19世紀後半のヨーロッパ</strong>では、各国が国力を強くするために<strong class=\"source-bold\">科学技術の開発</strong>を進めたよ<span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#859476\">➡P.121〜122</span>。特に、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファラデー</strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電磁誘導の法則</strong></span>を発見すると<strong class=\"source-bold\">発電機やモーターが発明</strong>され、<strong class=\"source-bold\">ダイムラー</strong>や<strong class=\"source-bold\">ディーゼル</strong>が<strong class=\"source-bold\">エンジン（内燃機関）を発明</strong>すると<strong class=\"source-bold\">自動車</strong>がつくられるようになり、世界の交通機関は大きく発達したんだ。そして、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">石油</strong></span>や<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">電力</strong></span>が<strong class=\"source-bold\">蒸気機関にかわる新しい動力</strong>になると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">重化学工業</strong></span>を中心に<strong class=\"source-bold\">石油産業、電機工業</strong>などの新しい産業が生まれたよ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次産業革命</strong></span>だ。</p>\n<p><strong class=\"source-bold\">19世紀半ばまで、世界の工業はイギリスがリード</strong>してきたけど、イギリスの産業は<strong class=\"source-bold\">綿工業を中心とする軽工業</strong>だったよね。イギリスはむちゃくちゃ<ruby>儲<rt>もう</rt></ruby>かっていたけど、第2次産業革命には出遅れちゃった。資本家は自分が儲かっていたから安心していたんだね。しかし、<strong class=\"source-bold\">イギリスに負けていたほかの国</strong>は、「なんとかしてイギリスに追いつきたい！」って思ってたから、資本家も国も、みんなが<strong class=\"source-bold\">技術開発や産業発展を目指していた</strong>わけだ。例えば、<strong class=\"source-bold\">南北戦争後のアメリカ</strong>は、北部を中心に工業発展を優先する政策をとったし、<strong class=\"source-bold\">ビスマルクが首相となったドイツ</strong>は国家予算をバンバンつぎ込んで、産業を発展させた。だから、<strong class=\"source-bold\">第2次産業革命はアメリカとドイツがリード</strong>したんだよ。</p>\n<blockquote><p>第1次産業革命は「蒸気機関」、第2次産業革命は「石油・電力」。動力の発展と主要産業の変化に注目してね</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">第2次産業革命が進んで、巨大企業が出現！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次産業革命</strong></span>で一番変わったのは、工場の規模だよ。<strong class=\"source-bold\">第1次産業革命の中心は綿工業</strong>だったから、最初はちょっとした町工場くらいのサイズでも工場が経営できた。それこそ、自分の家の庭とかにちょちょっと工場を建てることもできて（もちろん、規模が大きい工場もあるけどね）、イギリスでは産業資本家がかなりお金を貯めこんでた。でも<strong class=\"source-bold\">後進国のアメリカやドイツ</strong>の資本家は、そんなにお金を持ってない。しかも、<strong class=\"source-bold\">第2次産業革命が始まると、重化学工業が産業の中心</strong>になった。重化学工業の発展って製油所とか製鉄所とか火力発電所を建設するってことだよね。いきなりだけど、みんなの家に製油所とか製鉄所とかある？「あるわけないじゃん」とか思ったでしょ？ そう、普通はあるわけない。だって、こういった<strong class=\"source-bold\">大規模工場を建てる</strong>のって、何百億円とかっていう<strong class=\"source-bold\">膨大なお金がいる</strong>もんね。いきなり個人で出せる金額じゃない……。</p>\n<p>そこで<strong class=\"source-bold\">産業資本家たちは、資金を確保するために銀行と手を組んだ</strong>よ。銀行だって、有利な投資先をつくればもっと儲かるから、産業資本家と結びつくのも悪くな</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "202": "<h2>202</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p>い。こうして、<strong class=\"source-bold\">産業資本と銀行が結びついた金融資本</strong>が出現して、巨大な企業グループができたんだ。</p>\n<p>さらに、各企業がもっと利益を増やそうと、<strong class=\"source-bold\"><ruby>市場<rt>しじょう</rt></ruby>の独占</strong>を狙ったんだよ。みんなの身近なもので考えると、例えば、缶コーヒーをつくっている会社が日本に1つしかなかったとして、その会社が「今日から缶コーヒーは300円にします」って言ったら、世の中には300円の缶コーヒーしかなくなっちゃう。どうしても飲みたかったら買うしかないから、企業はボロ<ruby>儲<rt>もう</rt></ruby>けだ。これが<strong class=\"source-bold\">市場の独占</strong>ね。ちなみにこの時代には<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルテル</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トラスト</strong></span>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンツェルン</strong></span>による市場独占が進んだんだよ。</p>\n<h5><strong class=\"source-bold\">〈独占の形態〉</strong></h5>\n<div class=\"source-table-wrap\"><table><tbody><tr><td>名称</td><td>独占の形態</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルテル</strong></span><br>【企業連合】</td><td><span data-source-color=\"green\" style=\"color:#315837\">・</span><strong class=\"source-bold\">同一業種</strong>の企業が、価格や販売量などを<strong class=\"source-bold\">協定（各企業は別々のまま）</strong><br><span data-source-color=\"green\" style=\"color:#315837\">・</span>おもに<strong class=\"source-bold\">ドイツ</strong>で発達</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トラスト</strong></span><br>【企業合同】</td><td><span data-source-color=\"green\" style=\"color:#315837\">・</span><strong class=\"source-bold\">同一業種</strong>の企業が<strong class=\"source-bold\">合併</strong>して、1つの大企業となる<br><span data-source-color=\"green\" style=\"color:#315837\">・</span>おもに<strong class=\"source-bold\">アメリカ</strong>で発達（<strong class=\"source-bold\">スタンダード石油トラスト</strong>など）</td></tr><tr><td><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンツェルン</strong></span><br>【持株会社・<ruby>財閥<rt>ざいばつ</rt></ruby>】</td><td><span data-source-color=\"green\" style=\"color:#315837\">・</span><strong class=\"source-bold\">多種にわたる企業</strong>を、銀行などを中心に<strong class=\"source-bold\">1つの資本</strong>のもとに統合<br><span data-source-color=\"green\" style=\"color:#315837\">・</span>おもに<strong class=\"source-bold\">ドイツ</strong>や日本で発達（ドイツの<strong class=\"source-bold\">クルップ</strong>、日本の<strong class=\"source-bold\">財閥</strong>など）</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">独占資本主義の時代となり、世界分割が加速。帝国主義の始まり！</strong></span></h4>\n<p>こうして<strong class=\"source-bold\">各国で市場の独占が進む</strong>と、資本主義は自由競争の時代から、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">独占資本主義</strong></span>の時代に進んでいったよ。<strong class=\"source-bold\">中小の資本家は大企業に飲み込まれて</strong>しまい、市場を独占したごく少数の巨大企業は、「世界各地に製品を売って、もっと儲けたい！」って考え始めた。ただ、1870年代になると、ウィーンの証券取引所の暴落をきっかけに、<strong class=\"source-bold\">ヨーロッパは不況になった（19世紀末大不況）</strong>。ドイツやアメリカは保護貿易政策をとり、出遅れたイギリスは「世界の工場」から<strong class=\"source-bold\">「世界の銀行」</strong>に経済構造を転換していった。こうして植民地の意味が変わっていったんだ。<strong class=\"source-bold\">海外への投資（資本輸出）</strong>や石油などの<strong class=\"source-bold\">資源の独占が目標になってくる</strong>と、一企業の問題じゃなくなるよね。そう！ だから<strong class=\"source-bold\">各国は製品市場や投資先</strong>を確保して、さらに<strong class=\"source-bold\">石油などの資源</strong>を手に入れるためには、ほかの国よりもいっぱい植民地がほしい！ こうして、ヨーロッパ<ruby>列強<rt>れっきょう</rt></ruby>は<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義</strong></span>の時代に進んでいったんだよ。<strong class=\"source-bold\">アジアやアフリカは帝国主義の標的になった</strong>ってわけだ。</p>\n<blockquote><p>植民地の役割が「原料供給地・製品市場」に加えて「投資先（資本輸出）」になるよ</p></blockquote>",
  "203": "<h2>203</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ分割①（北部・東部・西部）</u></p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">アフリカ分割①（北部・東部・西部）</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">分割以前のアフリカは？ よくわからないから「暗黒大陸」</strong></span></h4>\n<p>分割以前のアフリカを、ヨーロッパ人たちは<strong class=\"source-bold\">文明のない未開の地</strong>という意味で、<strong class=\"source-bold\">「暗黒大陸」</strong>って呼んでたんだよ。これって、キリスト教じゃないから暗黒……みたいな、むちゃくちゃ上から目線の呼び方だな。</p>\n<p>しかし19世紀に入ると、ヨーロッパ人たちによる<strong class=\"source-bold\">「未知の領域」を探る動き</strong>が加速したんだ。代表的なのは<strong class=\"source-bold\">科学技術の発展</strong>なんだけど、科学技術だけじゃなくて、<strong class=\"source-bold\">アフリカやアジア</strong>、あるいは北極や南極などの、<strong class=\"source-bold\">未知の領域</strong>に踏み込んでいく人が現れた。このうち、アフリカ東部や南部の探検をしたのが<strong class=\"source-bold\">イギリス人<ruby>宣教師<rt>せんきょうし</rt></ruby></strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リヴィングストン</strong></span>だ。彼は探検をしながらキリスト教を<ruby>布教<rt>ふきょう</rt></ruby>し、さらにムスリム商人がやっている<ruby>奴隷<rt>どれい</rt></ruby>貿易を根絶しようとしたんだよ。そして、南アフリカの奥地で大きな滝（<strong class=\"source-bold\">ヴィクトリア<ruby>瀑布<rt>ばくふ</rt></ruby></strong>って名前になった）を見つけたあとに、あの<strong class=\"source-bold\">広大なアフリカ大陸で行方不明</strong>。こりゃー大事だ！ そして<strong class=\"source-bold\">アメリカ人探検家</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スタンリー</strong></span>は、<strong class=\"source-bold\">リヴィングストンの救出</strong>に向かい、タンガニーカで彼を発見すると、ヨーロッパ人として初めて<strong class=\"source-bold\">中央アフリカの横断に成功</strong>した。のちに、再び探検に行くんだけど、この時<strong class=\"source-bold\">スタンリーを援助</strong>したのが、ベルギー国王<strong class=\"source-bold\">レオポルド2世</strong>ね。これ、あとで事件になるから覚えておいてね。</p>\n<p>こうした探検によって、アフリカの内陸部の様子が明らかになってくると、<strong class=\"source-bold\">ヨーロッパ各国のアフリカ進出が加速</strong>していくよ。それじゃあ、具体的な進出について見ていこう。まずは、南アフリカを除く、<strong class=\"source-bold\">アフリカの北部・東部・西部</strong>の動きからだ！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスのアフリカ縦断政策。インドとインド航路を守る3C政策の一部だ！</strong></span></h4>\n<p><strong class=\"source-bold\">イギリスにとって一番重要な植民地はインド</strong>だったよね。イギリスの世界戦略では、インドを中心に<strong class=\"source-bold\">「インドを守ること」</strong>と<strong class=\"source-bold\">「本国イギリスとインドを結ぶ交通路を確保すること」</strong>が最も重要だった。じゃあ、インドに行く航路ってどこだろ？ 1つは<strong class=\"source-bold\">アフリカの南端を回るルート</strong>、もう1つは<strong class=\"source-bold\">地中海からエジプトを経由して、紅海からインド洋に抜けるルート</strong>だね。そうなると、重要なのは<strong class=\"source-bold\">「インド」「南アフリカ」</strong>そして</p>\n<blockquote><p><strong class=\"source-bold\">イギリス</strong><br><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">インド航路</span><br>カイロ<br>カルカッタ<br>ケープタウン<br><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3C政策</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "204": "<h2>204</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p><strong class=\"source-bold\">「エジプト」</strong>ってことになる。こうして進められたのが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">3C政策</strong></span>だよ。</p>\n<p>3C政策の<strong class=\"source-bold\">「3C」</strong>は、<strong class=\"source-bold\">エジプト</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カイロ</strong></span>（Cairo）、<strong class=\"source-bold\">インド</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">カルカッタ</strong></span>（Calcutta）、<strong class=\"source-bold\">南アフリカ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケープタウン</strong></span>（Cape Town）の頭文字を取った呼び方だけど、別に「この3都市だけでOK！」ってわけじゃないよ。<strong class=\"source-bold\">インド、エジプト、南アフリカを確保</strong>したうえで、この<strong class=\"source-bold\">3か所を頂点にした三角形</strong>の範囲は絶対に守る、ってことだ。そしてこの三角形、<strong class=\"source-bold\">アフリカ</strong>だけを見ると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト</strong></span><strong class=\"source-bold\">と</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケープ植民地</strong></span>を<strong class=\"source-bold\">結ぶ縦のライン</strong>ってことになるよね。これが、イギリスが進めた「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ縦断政策</strong></span>」だ！</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">イギリスのアフリカ縦断政策①（エジプトからの南下）</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河</strong></span>開通［1869］……<strong class=\"source-bold\">地中海と紅海をつなぐ</strong>運河<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">フランス人</strong>外交官<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レセップス</strong></span>が設立した<strong class=\"source-bold\">国際スエズ運河会社</strong>による</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河会社株の買収</strong></span>［1875］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディズレーリ</strong></span>《保守党》（第2次）内閣<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">運河の経営権をイギリスが掌握</strong>。以後、<strong class=\"source-bold\">イギリスはエジプト進出を強化</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウラービー運動</strong></span>［1881〜82］……エジプト最初の反英運動<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>イギリスは<strong class=\"source-bold\">エジプトを軍事<ruby>占領<rt>せんりょう</rt></ruby></strong>、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">事実上のエジプト保護国化</strong></span></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マフディー運動</strong></span>［1881〜98］……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スーダン</strong></span>のイスラーム教徒による反英闘争<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">ムハンマド=アフマドが自らをマフディー（救世主）</strong>と称して<ruby>蜂起<rt>ほうき</rt></ruby><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>イギリス軍人<strong class=\"source-bold\">ゴードン</strong>の戦死。マフディー軍は<strong class=\"source-bold\">ハルツーム</strong>に建国</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファショダ事件</strong></span>［1898］……<strong class=\"source-bold\">イギリスとフランスがスーダン南方で<ruby>対峙<rt>たいじ</rt></ruby></strong><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">フランスの譲歩</strong>で解決。<strong class=\"source-bold\">スーダンはイギリス領</strong>となった</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ヨーロッパからアジアへの近道、スエズ運河が完成！</strong></span></h4>\n<p><strong class=\"source-bold\">インドに行く航路</strong>は、大航海時代からずっと<strong class=\"source-bold\">アフリカの南を回るルートが中心</strong>だったけど、インドに着くまでに2回も赤道直下を通らなきゃいけないから、どう考えても健康に悪い。だって、当時は冷房がないんだもん……。このあたり、現代の感覚で考えちゃダメよ。しかも、大西洋は荒れるし……。だったら、海も穏やかで気候もよくて、しかも距離も短い<strong class=\"source-bold\">地中海経由のほうがいい！</strong> だから、地中海と紅海の接点にある<strong class=\"source-bold\">エジプトの重要性が高まっていた</strong>んだ。でもこのルート、エジプトで船を降りてスエズ地峡を馬車などで横断してから、再び船に乗る、って感じで何回も乗り換えなきゃいけなかった。それが<strong class=\"source-bold\">蒸気船</strong>の発達で状況が変わったよ。風向きに関係なく進める蒸気船の発達で、幅が大して広くない運河でも船が通れるようになったから、<strong class=\"source-bold\">地中海から紅海に抜ける運河</strong>を建設すれば、<strong class=\"source-bold\">インドに行く航路がむちゃくちゃ短くなる</strong>。</p>\n<p>「こりゃすごい！」って思ったのが<strong class=\"source-bold\">フランス</strong>だ。これまでフランスは、植民地</p>",
  "205": "<h2>205</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ分割①（北部・東部・西部）</u></p>\n<p>戦争でイギリスに負けっぱなしだったよね。こうなればスエズ運河で仕返しだ！ こうして、<strong class=\"source-bold\">フランス人</strong>外交官<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">レセップス</strong></span>が<strong class=\"source-bold\">国際スエズ運河会社</strong>を設立し、<strong class=\"source-bold\">エジプト政府とフランスが共同で工事を進める</strong>と、1869年、ついに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河</strong></span>が開通したよ。</p>\n<h5><strong class=\"source-bold\">〈アフリカ分割〉</strong></h5>\n<blockquote><p>チュニジア<br>アルジェリア<br>モロッコ<br>スペイン領モロッコ<br>トリポリ<br>キレナイカ<br>リビア（伊）<br>カイロ<br><strong class=\"source-bold\">エジプト</strong><br>エリトリア（伊）<br>ジブチ（仏）<br>セネガル<br><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">ファショダ事件［1898］</span><br>スーダン<br>ナイジェリア<br>アシャンティ<br><span data-source-color=\"white\" data-source-background=\"green\" style=\"color:#ffffff;background-color:#315837\">エチオピア帝国</span><br>カメルーン<br>トーゴ<br><strong class=\"source-bold\">リベリア共和国</strong><br>フランス領コンゴ<br>コンゴ自由国<br>（ベルギー領コンゴ）<br>ケニア<br>ソマリランド（伊）<br>東アフリカ<br>アンゴラ（ポルトガル）<br>モザンビーク（ポルトガル）<br>ローデシア<br>マダガスカル<br>南西アフリカ<br><strong class=\"source-bold\">トランスヴァール共和国</strong><br><strong class=\"source-bold\">オレンジ自由国</strong><br>ケープ植民地<br>ナタール<br>ケープタウン</p></blockquote>\n<div class=\"source-table-wrap\"><table><tbody><tr><td></td><td></td></tr><tr><td><span data-source-marker=\"fill\" style=\"color:#e52715\">■</span></td><td>イギリス</td></tr><tr><td><span data-source-marker=\"fill\" style=\"color:#f0a0a0\">■</span></td><td>フランス</td></tr><tr><td><span data-source-marker=\"fill\" style=\"color:#a6aaa0\">■</span></td><td>ドイツ</td></tr><tr><td><span data-source-marker=\"fill\" style=\"color:#315837\">■</span></td><td>独立国</td></tr><tr><td><span data-source-marker=\"dashed-arrow\" style=\"color:#e52715\">⇢</span></td><td>アフリカ縦断政策（英）</td></tr><tr><td><span data-source-marker=\"arrow\" style=\"color:#f0a0a0\">→</span></td><td>アフリカ横断政策（仏）</td></tr></tbody></table></div>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">借金を返せないエジプトから、イギリスがスエズ運河会社株を<ruby>買収<rt>ばいしゅう</rt></ruby>！</strong></span></h4>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河</strong></span>完成のニュースを聞いて、イギリスは焦った。「どうせ失敗するだろ」って思って<strong class=\"source-bold\">イギリスは出資してなかった</strong>から、運河の経営にはかかわれない。しかも、<strong class=\"source-bold\">エジプトと協力したのはフランス</strong>でしょ。フランスにエジプトとスエズ運河を取られたら、かなり不利になっちゃうじゃないか。</p>\n<p>そこで<strong class=\"source-bold\">イギリス</strong>は、<strong class=\"source-bold\">エジプト政府の<ruby>借款<rt>しゃっかん</rt></ruby></strong>に目をつけ、スエズ運河を赤字にさせる</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "206": "<h2>206</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p>作戦を開始！ スエズ運河を使わないことにしたの。近代化を進める<strong class=\"source-bold\">エジプト政府</strong>は、スエズ運河や鉄道、工場などの建設費として各国に借りたお金を、スエズ運河の通行料で返そうと思ってたんだけど、一番スエズ運河を使いそうなイギリスが、全然通ってくれない……。そして、ついに<strong class=\"source-bold\">借金が返せなくなった</strong>。そしたらイギリスは「借金返せないなら、スエズ運河でも売ったらどうだい」なんて言い出した。イジワルすぎるだろ。</p>\n<blockquote><p>スエズ運河はインドへの航路の重要拠点！ フランスに取られたら一大事だよ！</p></blockquote>\n<p>こうして<strong class=\"source-bold\">借金を返せなくなったエジプト政府</strong>は、<strong class=\"source-bold\">スエズ運河会社の株式を売る</strong>しかなくなった。この時、<strong class=\"source-bold\">イギリス首相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ディズレーリ</strong></span>は「フランスに買われる前に、さっさと買ってしまえ！」と考え、議会を通さずに<strong class=\"source-bold\">ロスチャイルド家から資金を借りて</strong>（当時の年間税収の約5％にあたる400万ポンド）、<strong class=\"source-bold\">エジプト政府保有分</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スエズ運河会社株を<ruby>買収<rt>ばいしゅう</rt></ruby></strong></span>した。これって大問題だよ。実際、自由党のグラッドストンが、この対応を議会で批判している。でも、これで<strong class=\"source-bold\">イギリスが最大株主</strong>になって<strong class=\"source-bold\">スエズ運河会社の経営権を握った</strong>んだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスの進出に対し、エジプトとスーダンで抵抗運動が起きた！</strong></span></h4>\n<p><strong class=\"source-bold\">スエズ運河を確保したイギリス</strong>は、運河の安全を守るために<strong class=\"source-bold\">エジプトへの進出を強化</strong>した。ただ、エジプトにしてみればただの<ruby>侵略<rt>しんりゃく</rt></ruby>だから、イギリスに反発する動きが起こった。エジプトの軍人<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウラービー</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オラービー</strong></span>】は、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフガーニー</strong></span>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パン=イスラーム主義</strong></span>の影響も受けて、<strong class=\"source-bold\">「エジプト人のためのエジプト」</strong>というスローガンを掲げてクーデタを起こし、<strong class=\"source-bold\">憲法制定や議会の開設</strong>などを目指した（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウラービー運動</strong></span>）。すると民衆にまで運動が拡大し始めたから、これを<ruby>潰<rt>つぶ</rt></ruby>すためにイギリスは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト</strong></span>を<strong class=\"source-bold\">軍事<ruby>占領<rt>せんりょう</rt></ruby></strong>し、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">事実上の保護国</strong></span>にした（イギリスから見ると<strong class=\"source-bold\">「ウラービーの反乱を<ruby>鎮圧<rt>ちんあつ</rt></ruby>した」</strong>ってことになる）。あっ！ 正式に保護国化する条約とかを結んだわけじゃないから<strong class=\"source-bold\">「事実上」</strong>だからね（<strong class=\"source-bold\">正式な保護国化は1914年</strong>だ）。</p>\n<p>さらに<strong class=\"source-bold\">イギリス</strong>がエジプトから<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スーダン</strong></span>の<strong class=\"source-bold\">支配権を奪って</strong>軍隊を進めると、<strong class=\"source-bold\">スーダン</strong>でも<strong class=\"source-bold\">ムハンマド=アフマド</strong>を指導者とする<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">マフディー運動</strong></span>が起きたんだ。<strong class=\"source-bold\">マフディー</strong>っていうのは、<strong class=\"source-bold\">イスラーム教の救世主</strong>のことだよ。イギリスは、こんな抵抗はあっという間に鎮圧できると思ってたんだけど、予想外の大苦戦。マフディー軍は<strong class=\"source-bold\">ハルツーム</strong>を占領して国家を建設し、イギリス軍では<strong class=\"source-bold\">ゴードン将軍も戦死</strong>……。結局、<strong class=\"source-bold\">鎮圧までに18年もかかってしまった</strong>。これは、大誤算だよ！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">イギリスが手こずってる間に、アフリカ分割の原則が決まった！</strong></span></h4>\n<p>イギリスがマフディー軍の鎮圧に手こずっているころ、<strong class=\"source-bold\">アフリカをめぐる状況は大きく変わった</strong>よ。それが、1884〜85年に<strong class=\"source-bold\">コンゴ問題</strong>に関して開かれた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン会</strong></span></p>",
  "207": "<h2>207</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">2</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ分割①（北部・東部・西部）</u></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">議</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ベルリン=コンゴ会議</strong></span>】だ。</p>\n<p>きっかけは、<strong class=\"source-bold\">ベルギーのコンゴ進出</strong>だよ。<strong class=\"source-bold\">ベルギー国王レオポルド2世</strong>が、アフリカ中部の横断に成功した<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">スタンリー</strong></span>を雇って<strong class=\"source-bold\">コンゴ国際協会</strong>を設立し、1883年には<strong class=\"source-bold\">コンゴの領有を宣言</strong>したんだけど、<strong class=\"source-bold\">各国が猛反発！</strong> <strong class=\"source-bold\">ベルギーは弱小国</strong>だからね。<strong class=\"source-bold\">イギリス</strong>や<strong class=\"source-bold\">ポルトガル</strong>が「ベルギーのくせに生意気な」と怒った！ ここに<ruby>介入<rt>かいにゅう</rt></ruby>してきたのが、<strong class=\"source-bold\">ドイツ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ビスマルク</strong></span>だよ。</p>\n<p>ビスマルクはコンゴ問題をうまいこと利用した。独仏の連携をちらつかせてイギリスの譲歩を引き出し、フランスを対外進出に向かわせてドイツの安全を図り、さらに列強の勢力均衡を図りながら、<strong class=\"source-bold\">ドイツもアフリカ進出の機会を狙い</strong>、最終的に<strong class=\"source-bold\">ドイツを中心とする大国の国際関係をつくる</strong>。ビスマルクは策略家だな。</p>\n<p>こうして<strong class=\"source-bold\">ベルリン会議</strong>では、<strong class=\"source-bold\">「<ruby>先占<rt>せんせん</rt></ruby>権」</strong>、<strong class=\"source-bold\">「実効支配」</strong>、<strong class=\"source-bold\">「境界確定」</strong>という原則が確認された。先占権っていうのは、アフリカは誰のものでもない（無主の地だ）から<strong class=\"source-bold\">「先に占領した国が領有してもいい」</strong>、実効支配っていうのは<strong class=\"source-bold\">「実際に役人やら軍隊を派遣して<ruby>統治<rt>とうち</rt></ruby>機構ができている」</strong>ってこと、そして、<strong class=\"source-bold\">「沿岸部を植民地にしたら、後背地（隣接する内陸）も保有できる」</strong>のが境界確定だ。つまり、アフリカの植民地化は<strong class=\"source-bold\">「早い者勝ち！」</strong>ってことになったから、<strong class=\"source-bold\">コンゴはベルギーのものになる</strong>。結果、<strong class=\"source-bold\">ベルギー国王レオポルド2世の私領</strong>として<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">コンゴ自由国</strong></span>ができた。ただ「早い者勝ち」ってことになると、<strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby>のアフリカ分割が加速</strong>するよね。だから会議のあと、ドイツのビスマルクも、<strong class=\"source-bold\">トーゴ、カメルーン、南西アフリカ、東アフリカ（タンガニーカ）</strong>の4つの植民地を形成したよ。この時、南西アフリカでは現地の<strong class=\"source-bold\">ヘレロ人がドイツ軍に大量虐殺されている</strong>んだ。ちなみに、ベルリン会議ではコンゴ川、およびニジェール川の自由航行と、自由貿易および<ruby>奴隷<rt>どれい</rt></ruby>貿易の禁止もあわせて決まったから、難関大を受けるならおさえておこう。</p>\n<blockquote><p>コンゴ自由国は、現地の人にはなんの自由もない！ 過酷な強制労働などがおこなわれたんだ</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">先占権が確認されて、フランスがアフリカ進出を加速！</strong></span></h4>\n<p><strong class=\"source-bold\">フランス</strong>は1830年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">シャルル10世</strong></span>が出兵して、すでに<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アルジェリア</strong></span>を領有し、さらに、1878年の<strong class=\"source-bold\">ベルリン会議</strong>（これは<strong class=\"source-bold\">東方問題をめぐるベルリン会議</strong>ね）で優先権を認められた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">チュニジア</strong></span>を保護国にしていたんだけど、ベルリン=コンゴ会議のあと、「早い者勝ちなら、イギリスに取られる前にアフリカをどんどん取ってしまえ！」って思って、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アフリカ横断政策</strong></span>を進めたよ。</p>\n<p>まず、<strong class=\"source-bold\">アルジェリアとセネガルを結ぶ</strong>ため、西アフリカから赤道アフリカへと進出したよ。ギニアでは<strong class=\"source-bold\">サモリ=トゥーレ</strong>の抵抗に阻まれながらもこれを鎮圧し、征服した。また、<strong class=\"source-bold\">ガーナで衝突した英仏両国</strong>は、アシャンティ王国をイギリスが、ダ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "208": "<h2>208</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p>ホメ王国をフランスが支配することを決めた。アフリカ東部では、<strong class=\"source-bold\">イギリス、イタリアとソマリランド</strong>を分割して海港都市<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジブチ</strong></span>を建設すると、<strong class=\"source-bold\">西アフリカとの連結</strong>を目指して、南スーダンへと進軍し、さらに<strong class=\"source-bold\">マダガスカル</strong>にも進出した。</p>\n<p>こんなふうに<strong class=\"source-bold\">フランス</strong>は、とにかく軍を進めて赤・白・青の三色旗（フランス国旗）をアフリカに立てまくった！ だって<strong class=\"source-bold\"><ruby>先占<rt>せんせん</rt></ruby>権</strong>だし、<strong class=\"source-bold\">とっとと<ruby>占領<rt>せんりょう</rt></ruby>して役人やら軍隊を置けばいい！</strong> 気がつけば、<strong class=\"source-bold\">南スーダンまでフランスが進出</strong>していたんだ。フランスの動きを警戒した<strong class=\"source-bold\">イギリス</strong>は、<strong class=\"source-bold\">イタリア</strong>に対して<strong class=\"source-bold\">「今のうちにエチオピアに進出しちゃえ！」</strong>って背中を押した。だって、イギリスはマフディー軍との戦いで身動きが取れないんだもん。「フランスに取られるくらいならイタリアのほうがマシだ」ってことだね。イタリアも<ruby>舐<rt>な</rt></ruby>められたもんだ。こうして<strong class=\"source-bold\">イタリアは、エリトリア、ソマリランド</strong>に続いて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エチオピア</strong></span>を征服するために出兵したんだけど、なんと<strong class=\"source-bold\">アドワの戦いでエチオピアに負けた</strong>……！。だって、エチオピア軍の持っていた武器が強かったんだもん。これね、<strong class=\"source-bold\">フランス</strong>がイタリアの動きを警戒して、<strong class=\"source-bold\">エチオピアに武器を援助</strong>してたんだよ。イタリアにしてみれば「ズルいじゃないか〜」って気分だよね。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ついに英仏両国が衝突。ファショダ事件で緊張は最高潮！</strong></span></h4>\n<p>18年もかかって、<strong class=\"source-bold\">イギリスはマフディー運動を<ruby>鎮圧<rt>ちんあつ</rt></ruby></strong>すると南へと軍を進めた。そして、<strong class=\"source-bold\">スーダン南方の町ファショダ</strong>まできた時、とんでもなく不愉快な物を見つけた……「なんだ、あの目障りな三色旗は！」。そう、イギリスがくる前にすでに<strong class=\"source-bold\">フランスがファショダを占領</strong>していたんだ。イギリスのキッチナー将軍は、フランスのマルシャン大佐に<strong class=\"source-bold\"><ruby>撤退<rt>てったい</rt></ruby>を要求</strong>したけど、フランスだって「はい、そうですか」と撤退するわけない。こうして1898年、<strong class=\"source-bold\">英仏両国が直接<ruby>対峙<rt>たいじ</rt></ruby></strong>する<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ファショダ事件</strong></span>が起きたんだ。</p>\n<blockquote><p>イギリスの縦断政策、フランスの横断政策。ついに衝突したのがファショダ事件だ！</p></blockquote>\n<p>ただ、ファショダのフランス軍は戦う気はなかっただろうね。てか、戦っても100%負ける。だって、ファショダにいたフランス軍はわずか300人弱。対するイギリス軍は4万人に迫る勢いだからね。でも、<strong class=\"source-bold\">英仏両軍は</strong>それぞれの政府に<strong class=\"source-bold\">「本国の政府同士で決めてください。</strong>指示に従います」と連絡した。もし開戦すればフランスも援軍を送ってくるだろうから、大規模な戦争になりかねないもんね。</p>\n<p>この時、<strong class=\"source-bold\">イギリス首相ソールズベリ</strong>は<strong class=\"source-bold\">「スーダンは絶対に譲らない！」</strong>と宣言し、世論もこれを支持した。一方のフランスは……さすがに開戦できなかった。だって、<strong class=\"source-bold\">本国ではドレフュス事件が起きて</strong>、国論が二分されてて戦争どころじゃないし、ドイツの動きも気になる。そう！ <strong class=\"source-bold\">当時の英仏両国は、ドイツの動きを警戒していた</strong>んだよ。</p>",
  "209": "<h2>209</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">アフリカ分割②（南アフリカ）</u></p>\n<p><strong class=\"source-bold\">ファショダ事件</strong>が起きたころ、すでにドイツでは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>の<strong class=\"source-bold\">親政</strong>が始まり、ガンガン対外進出する「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界政策</strong></span>」を進めていた。もし英仏戦争が始まったら、その隙にドイツの対外進出が加速して、下手すりゃ<strong class=\"source-bold\">ドイツだけが得をする可能性が高い</strong>。どっちもドイツがムカつくから、「キライなヤツが一致すると愛が芽生える」。外交と恋愛は似たようなもんだ。こうして英仏が接近し始め、<strong class=\"source-bold\">フランスがスーダンから撤退</strong>して、<strong class=\"source-bold\">スーダンはイギリス領</strong>になったんだ。</p>\n<p>そして、<strong class=\"source-bold\">ファショダ事件で開戦を回避</strong>した両国は、1904年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span>を結んで、<strong class=\"source-bold\">イギリス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エジプト</strong></span>、<strong class=\"source-bold\">フランス</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">モロッコ</strong></span>優先権を相互に承認して、両国の勢力圏を決めたんだ。ていうか、イギリスはズルい。考えてみて！ <strong class=\"source-bold\">「イギリスがすでに確保してるエジプトをもらう</strong>から、<strong class=\"source-bold\">フランスはまだ誰も取っていないモロッコを取っていいよ！」</strong>ってことでしょ。フランス以外にもモロッコがほしい国はあるんじゃないの？ これ、あとで問題になるからね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">3</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">アフリカ分割②（南アフリカ）</strong></span></h3>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">クローズアップ</strong></span> <strong class=\"source-bold\">イギリスのアフリカ縦断政策②（ケープ植民地からの北上）</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケープ植民地</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィーン議定書</strong></span>で<strong class=\"source-bold\">イギリスがオランダから獲得</strong><br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">オランダ系</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブール人</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボーア人</strong></span>】はイギリス人の圧迫で<strong class=\"source-bold\">北方に移住</strong><br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">ナタール共和国</strong>建設［1838］……<em data-source-italic=\"true\" style=\"font-style:italic\">海岸地帯だったため、イギリスが征服</em>［1843］<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トランスヴァール共和国</strong></span>［1852］、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オレンジ自由国</strong></span>［1854］建設<br>……世界屈指の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金・ダイヤモンド鉱</strong></span>発見</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ケープ植民地首相</strong>：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セシル=ローズ</strong></span>［任1890〜96］による<ruby>侵略<rt>しんりゃく</rt></ruby><br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローデシア</strong></span>征服［1890〜94］……南アフリカ内陸部征服。セシル=ローズが命名</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ戦争</strong></span>［1899〜1902］……植民相：<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョゼフ=チェンバレン</strong></span>が推進<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span><strong class=\"source-bold\">トランスヴァール共和国、オレンジ自由国を征服</strong></p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ連邦</strong></span>成立［1910］……イギリスの<strong class=\"source-bold\">自治領</strong>となった<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span>成立当初から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アパルトヘイト</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人種<ruby>隔離<rt>かくり</rt></ruby>政策</strong></span>）をおこなう</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ブール人は内陸に移住。しかし、イギリスは北へと勢力拡大！</strong></span></h4>\n<p>それじゃあ、<strong class=\"source-bold\">南アフリカ</strong>の動きを見ていこう。イギリスは<strong class=\"source-bold\">ナポレオン戦争中</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケープ植民地</strong></span>を占領して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ウィーン議定書</strong></span>で正式に植民地にしたよね。<strong class=\"source-bold\">ケープ植民地はもともとオランダ領</strong>だったから、<strong class=\"source-bold\">オランダ系移民の子孫</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブール人</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ボーア人</strong></span>】が住んでいたんだよ。彼らはイギリスの支配下に入るのがイヤだったから、<strong class=\"source-bold\">ケープ植</strong></p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "210": "<h2>210</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p><strong class=\"source-bold\">民地を離れて移住（グレート=トレック）</strong>を始め、<strong class=\"source-bold\">北側の海岸沿い</strong>にあった先住民のズールー王国を破って、<strong class=\"source-bold\">ナタール共和国</strong>を建てたんだ。</p>\n<p>ただ、インドへの航路を確保したいイギリスは、ブール人が海岸沿いにいるのは気に食わない。<strong class=\"source-bold\">ナタール共和国はすぐにイギリスに征服されて</strong>しまい、ブール人はさらに内陸に移住して、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トランスヴァール共和国</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">オレンジ自由国</strong></span>を建てたよ。イギリスは最初、「内陸なんて砂漠しかないだろ、ザマー見ろ」って思ってたら、全然ザマー見ろじゃなくなった。なんと、トランスヴァールとオレンジで<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">金鉱</strong></span>と<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ダイヤモンド鉱</strong></span>が発見されたんだ！。</p>\n<blockquote><p>一気に金とダイヤの大産地へ！ だからイギリスに狙われたんだよなぁ</p></blockquote>\n<p>こうなると状況は変わるね。金とダイヤを求めて<strong class=\"source-bold\">イギリス人がトランスヴァールやオレンジに投資し始めた</strong>。代表的なのが、<strong class=\"source-bold\">帝国主義者</strong>として有名な<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セシル=ローズ</strong></span>だよ。ローズは<strong class=\"source-bold\">金やダイヤモンドの鉱山を次々と買い占める</strong>と、その富を背景に政界に進出し、<strong class=\"source-bold\">ケープ植民地首相</strong>になった。そして、<strong class=\"source-bold\">トランスヴァールへの勢力拡大</strong>を進め、さらに勢力圏をスーダンまでつなごうと、<strong class=\"source-bold\">北方への<ruby>侵略<rt>しんりゃく</rt></ruby></strong>を始めたんだ。</p>\n<p>あっ！ この時はまだ<strong class=\"source-bold\">本国は<ruby>介入<rt>かいにゅう</rt></ruby>していない</strong>よ。だって、<strong class=\"source-bold\">マフディー運動が<ruby>鎮圧<rt>ちんあつ</rt></ruby>できていない</strong>んだもん。でも、現地のヤツらにはそんなことは関係ない。セシル=ローズは<strong class=\"source-bold\">中央アフリカまで領土を拡大</strong>すると、自分の名前にちなんで「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローデシア</strong></span>」と名づけた。さらに、<strong class=\"source-bold\">トランスヴァールの<ruby>併合<rt>へいごう</rt></ruby>を狙って</strong>軍を送ったんだけど<strong class=\"source-bold\">ブール人の抵抗で失敗</strong>、これが原因で失脚することになったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ついにイギリス本国が介入。南アフリカ戦争が始まった！</strong></span></h4>\n<p><strong class=\"source-bold\">マフディー運動鎮圧ののち、ファショダ事件でスーダンを確保</strong>すると、いよいよ<strong class=\"source-bold\">本国の直接介入</strong>が始まり、<strong class=\"source-bold\">ソールズベリ</strong>内閣の<strong class=\"source-bold\">植民相</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョゼフ=チェンバレン</strong></span>は南アフリカに軍隊を送ったんだ。こうして始まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南ア戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブール戦争</strong></span>】でブール人を<ruby>舐<rt>な</rt></ruby>めていたイギリスは、「どうせ数カ月で勝てるだろう」</p>\n<h4><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">合</strong></span><span data-source-color=\"white\" data-source-background=\"brown\" style=\"color:#ffffff;background-color:#a43725\"><strong class=\"source-bold\">否</strong></span><strong class=\"source-bold\">の分かれ目</strong> <strong class=\"source-bold\">南アフリカ侵略を推進した政治家</strong></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セシル=ローズ</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ケープ植民地首相</strong></span> <span data-source-color=\"green\" style=\"color:#315837\">⬅</span><strong class=\"source-bold\"><u data-source-underline-color=\"gray\" style=\"text-decoration-color:#777777\">現地</u>の政治家</strong>だよ<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><strong class=\"source-bold\">中央アフリカ</strong>征服<span data-source-color=\"green\" style=\"color:#315837\">➡</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ローデシア</strong></span>と命名</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョゼフ=チェンバレン</strong></span>……<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">植民相</strong></span>（<strong class=\"source-bold\">ソールズベリ内閣</strong>） <span data-source-color=\"green\" style=\"color:#315837\">⬅</span><strong class=\"source-bold\"><u data-source-underline-color=\"gray\" style=\"text-decoration-color:#777777\">本国</u>の政治家</strong>だよ<br><span data-source-color=\"green\" style=\"color:#315837\">▶</span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ戦争</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南ア戦争</strong></span>／<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ブール戦争</strong></span>】を推進</p></blockquote>",
  "211": "<h2>211</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの「世界政策」とモロッコ事件</u></p>\n<p>って思っていたんだけど、この予測がむちゃくちゃ甘かったんだよ。</p>\n<p>戦争は3年弱も続き、<strong class=\"source-bold\">苦戦したイギリス</strong>は45万人もの兵士を南アフリカに送ることになった。しかも戦死者は2万人以上！。しかも、イギリスが使った戦費は2億ポンド以上（これって、当時の年間税収の約3倍だよ！）。これだけの人とお金を使ってなんとか<strong class=\"source-bold\">トランスヴァールとオレンジを併合</strong>したけど、この戦争のあと、イギリスは外交戦略を見直す必要に迫られたんだよ。</p>\n<p>イギリスは<strong class=\"source-bold\">南ア戦争の戦費で財政難</strong>となり、かえって国際的な影響力が弱まってしまった。例えば、<ruby>義和団<rt>ぎわだん</rt></ruby>事件の際の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">8カ国共同出兵</strong></span>で<strong class=\"source-bold\">イギリス軍があまり出兵できなかった</strong>のは南ア戦争中だったからだし、終戦後の1902年には、東アジアでの<strong class=\"source-bold\">ロシアの勢力拡大を抑えるために</strong>、「光栄ある孤立」を捨てて<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日英同盟</strong></span>を結ぶことになるしね。</p>\n<blockquote><p>金とダイヤを取ったら財政難になった……<br>イギリスがついに「光栄ある孤立」を捨てるよ！</p></blockquote>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ブール人をなだめるために、アパルトヘイトが始まった！</strong></span></h4>\n<p>イギリスは1910年、<strong class=\"source-bold\">ケープ、トランスヴァール、オレンジ、ナタール</strong>の4州からなる<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">南アフリカ連邦</strong></span>を形成し、<strong class=\"source-bold\">自治領</strong>にしたよ。この自治領で政権に<ruby>就<rt>つ</rt></ruby>いたのは実はブール人なんだよ……。トランスヴァールの一部の軍人たちが、自分たちの自治権を回復するためにイギリスに協力し、<strong class=\"source-bold\">イギリスもブール人を味方にするために</strong>、「同じ白人同士なんだから、<strong class=\"source-bold\">黒人を<ruby>弾圧<rt>だんあつ</rt></ruby>して仲良くやりましょう</strong>」って、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アパルトヘイト</strong></span>（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">人種<ruby>隔離<rt>かくり</rt></ruby>政策</strong></span>）を始めた。ひどい話だな。1991年まで続く黒人への人種隔離政策は、こんなふうにイギリスが始めたんだよ。</p>\n<p>そして、この時期にはすでに<strong class=\"source-bold\">人種差別の撤廃を求める運動</strong>が始まっているんだ。南アフリカでは1912年に南アフリカ先住民民族会議（1923年に<strong class=\"source-bold\">アフリカ民族会議【ANC】</strong>に改称）が結成され、<strong class=\"source-bold\">非暴力主義</strong>によってアパルトヘイトへの反対運動をおこなったんだけど、白人政権はこれを弾圧した。ここから長い闘いの歴史が始まるんだね。</p>\n<h3><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\"><strong class=\"source-bold\">ドイツの「世界政策」とモロッコ事件</strong></span></h3>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">ドイツが「世界政策」を開始して、第1次モロッコ事件が<ruby>勃発<rt>ぼっぱつ</rt></ruby>！</strong></span></h4>\n<p>最後はアフリカをめぐる<strong class=\"source-bold\">ドイツと英仏の対立</strong>について見ていこう。1890年に<strong class=\"source-bold\">ビスマルクが退陣</strong>すると、<strong class=\"source-bold\">ドイツ</strong>では皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>の<strong class=\"source-bold\">親政</strong>が始まり、国内の発展を優先して<strong class=\"source-bold\">対外進出をあまりしなかったビスマルク</strong>の方針を<strong class=\"source-bold\">180度ひっくり返した</strong>んだよ。19世紀末には、ドイツはすでにイギリスと並ぶような工業国に発展していたから（だいたい<strong class=\"source-bold\">1900年ころに工業生産でイギリスを抜く</strong>よ）、国内では「ドイ</p>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "212": "<h2>212</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<p>ツもガンガン海外に進出してほしい！」っていう空気もあったんだよ。こうして、ヴィルヘルム2世は<strong class=\"source-bold\">「ドイツの将来は海上にあり！」</strong>として<strong class=\"source-bold\">海軍を強化</strong>し、強引に世界各地に進出していく「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">世界政策</strong></span>」を進めた。そして、20世紀に入ると、大事件が起こったんだよ。</p>\n<p>1904年に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">英仏協商</strong></span>が成立して、<strong class=\"source-bold\">イギリスのエジプト、フランスのモロッコでの優先権</strong>を相互承認すると、<strong class=\"source-bold\">フランスはモロッコに進出</strong>し始めた。まあ、フランスは「モロッコは勝手に取っちゃっていい」って思ってるからね。でも、ドイツは気に食わない。ヴィルヘルム2世は「英仏で勝手に決めて、フランスがモロッコを取るとはけしからん」と思った。そして、ついに行動を起こしたんだよ。</p>\n<h5><strong class=\"source-bold\">〈モロッコ事件〉</strong></h5>\n<blockquote><p><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">第1次モロッコ事件［1905］</span><br>アルヘシラス<br><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">第2次モロッコ事件［1911］</span><br>タンジール<br>アルジェリア（仏）<br>チュニジア（仏）<br>モロッコ<br>アガディール<br>トリポリ<br>リビア（伊・1912）<br>キレナイカ<br><span data-source-border=\"red\" style=\"border:1px solid #e52715;padding:0 0.2em\">イタリア=トルコ戦争［1911〜12］</span></p></blockquote>\n<p>1905年、地中海クルーズをしていた<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>は、突然「モロッコに行け！」と言いだし、<strong class=\"source-bold\">モロッコ</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンジール</strong></span>を<strong class=\"source-bold\">訪問</strong>すると、「モロッコは誰のものでもない。<strong class=\"source-bold\">すべての国に<ruby>門戸<rt>もんこ</rt></ruby>が開かれるべきである！</strong>」と、世界に向けて発言したんだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次モロッコ事件</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">タンジール事件</strong></span>】だよ。ヴィルヘルム2世は、劇的な事件を起こして英仏の仲を悪くさせたかったんだよね。でも、すでに<strong class=\"source-bold\">英仏協商を結んでいる両国は、協力してドイツに対抗した</strong>。だって、フランスがモロッコを取ってくれないと、イギリスのエジプト優先権の根拠がなくなるでしょ。</p>\n<blockquote><p>たいして仲良くなかった英仏は、モロッコ事件を通じて「英仏協商が正しかった」って思うようになるんだ</p></blockquote>\n<p>こうして開かれた<strong class=\"source-bold\">アルヘシラス会議</strong>では、<strong class=\"source-bold\">イギリスがフランスを支持</strong>しただけじゃなくて、</p>",
  "213": "<h2>213</h2>\n<p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">4</strong></span> <u data-source-underline-color=\"red\" style=\"text-decoration-color:#e52715\">ドイツの「世界政策」とモロッコ事件</u></p>\n<p>ロシア、イタリア、アメリカまでもがフランスを支持したので、<strong class=\"source-bold\">ドイツは孤立</strong>しちゃった。ドイツは、いったん<ruby>諦<rt>あきら</rt></ruby>めるしかなくなったんだね。そしてこの会議では、<strong class=\"source-bold\">モロッコをフランスとスペインの勢力範囲にする</strong>ことが決まったんだ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">またもやヴィルヘルム2世が、第2次モロッコ事件を起こした！</strong></span></h4>\n<p>それでもヴィルヘルム2世は諦めなかった。1911年、<strong class=\"source-bold\">モロッコ</strong>でフランスに対する<strong class=\"source-bold\">ベルベル人の反乱</strong>が起きると、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ヴィルヘルム2世</strong></span>は突然、<strong class=\"source-bold\">軍艦をモロッコの</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アガディール</strong></span><strong class=\"source-bold\">に派遣した</strong>んだ。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第2次モロッコ事件</strong></span>【<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">アガディール事件</strong></span>】だよ。</p>\n<p>この時ヴィルヘルム2世は、<strong class=\"source-bold\">「フランスがモロッコを取るなら、ドイツにも何かくれ！」</strong>って言いたかったんだけど、それだけなら外交でなんとかすればいい。実際、フランスはモロッコをめぐってドイツと戦争をする気はなかったから、外交交渉でもたぶんなんとかなったんだよ。でも、<strong class=\"source-bold\">軍艦を派遣するっていうのはタダゴトじゃない</strong>！。これに敏感に反応したイギリスは、海軍の出動を準備した。</p>\n<p>最終的には、フランスがモロッコを取るかわりに、<strong class=\"source-bold\">ドイツはフランス領コンゴの一部（カメルーンの隣ね）を獲得</strong>することで話し合いがまとまったんだけど、もはやモロッコだけの問題じゃなくなった。<strong class=\"source-bold\">モロッコ事件はヨーロッパの国際対立を激化</strong>させ、独仏関係が悪くなる以上に、<strong class=\"source-bold\">英独関係を悪化させてしまった</strong>んだよ。イギリスはドイツに対する警戒感を強め、フランス国内でも「弱腰外交だ！」って批判が起きたから、結果として<strong class=\"source-bold\">英仏が対ドイツでさらに接近</strong>したんだよ。モロッコ事件の経緯は、第一次世界大戦前の国際関係で重要になるから、しっかり確認してね！</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">第2次モロッコ事件のドサクサに紛れて、イタリアがリビアに進出！</strong></span></h4>\n<p><strong class=\"source-bold\">第2次モロッコ事件</strong>ではイギリス軍まで出動準備を始めたから、全世界が「イギリスとドイツが戦争になるんじゃないか」って警戒していた。ってことは、<strong class=\"source-bold\">誰もイタリアに興味がない</strong>。イタリアにとっては「目立たないように植民地を取るチャンス」だ。こうして<strong class=\"source-bold\">イタリア</strong>は、1911年から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">イタリア=トルコ戦争</strong></span>を戦って勝利すると、<strong class=\"source-bold\">ローザンヌ条約</strong>でオスマン帝国から<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">トリポリ・キレナイカ</strong></span>を奪って、「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リビア</strong></span>」と改称したよ。なんでリビアか？っていうと、ローマ帝国時代の名前だよ。イタリアの夢は「ローマ帝国復活」だからね。</p>\n<blockquote><p>世界中が「英仏 vs. 独の戦争か」って言ってる時にリビアを取るなんて、イタリアはちゃっかりしてるな</p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第1章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">国民国家の形成</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第2章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">列強の侵略とアジアの変革</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">第3章</strong></span> <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">帝国主義と第一次世界大戦</strong></span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第4章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦間期と第二次世界大戦</span></p></blockquote>\n<blockquote><p><span data-source-color=\"white\" data-source-background=\"gray\" style=\"color:#ffffff;background-color:#a6aaa0\"><strong class=\"source-bold\">第5章</strong></span> <span data-source-color=\"gray\" style=\"color:#777777\">戦後の世界</span></p></blockquote>",
  "214": "<h2>214</h2>\n<p><span data-source-color=\"white\" data-source-background=\"black\" style=\"color:#ffffff;background-color:#001000\"><strong class=\"source-bold\">第11回</strong></span> 帝国主義とアフリカ分割</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\">◀</span> <span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">アフリカ分割が完了して、独立国として残ったのはたったの2国！</strong></span></h4>\n<p>さて、<strong class=\"source-bold\"><ruby>列強<rt>れっきょう</rt></ruby>のアフリカ分割</strong>によって、ほとんどの地域がどこかの国の植民地になっちゃったよね。じゃあ<strong class=\"source-bold\">独立国として残った国</strong>なんてあるのかな？ 第一次世界大戦が始まる直前の時点で、<strong class=\"source-bold\">独立国として残っていたのはわずか2国、エチオピア帝国とリベリア共和国だけ</strong>なんだよ。</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">エチオピア帝国</strong></span>は、さっき話したように<strong class=\"source-bold\">イタリア軍をアドワの戦いで<ruby>撃退<rt>げきたい</rt></ruby></strong>しているから独立を守れたっていうのもあるんだけど、もう一つ重要なことがあるよ。それが<strong class=\"source-bold\">「英仏の<ruby>緩衝<rt>かんしょう</rt></ruby>地帯」</strong>ってことだ。英仏両国はファショダ事件で開戦を回避しているから、何も今さら<strong class=\"source-bold\">エチオピアを取り合って戦争する必要はない</strong>よね。しかも、20世紀に入ると<strong class=\"source-bold\">ドイツに対する警戒感が強くなる</strong>から、もはや協力するしかない。だから、<strong class=\"source-bold\">エチオピアは独立国として残す</strong>ことにしたんだよ。</p>\n<p>そしてもう一つの<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">リベリア共和国</strong></span>。リベリアは、アメリカ合衆国北部で創設された<strong class=\"source-bold\">アメリカ植民協会</strong>が、<strong class=\"source-bold\">「解放された<ruby>奴隷<rt>どれい</rt></ruby>をアフリカに返そう！」</strong>ってつくった国なんだよ。ちなみに<strong class=\"source-bold\">国名のリベリアは英語のliberty</strong>から、<strong class=\"source-bold\">首都のモンロヴィアはアメリカ大統領モンロー</strong>にちなんだ名前ね。入植が始まった時にアメリカ大統領だったのがモンローだからね。ってことは、リベリアを植民地になんてできるわけない。アメリカにケンカを売ることになるもんね。</p>\n<p>じゃあ、これでアフリカ分割はおしまい！ 最後に年号 check だよ。</p>\n<h4><span data-source-color=\"green\" style=\"color:#315837\"><strong class=\"source-bold\">‼</strong></span><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">年号</strong></span><span data-source-color=\"white\" data-source-background=\"red\" style=\"color:#ffffff;background-color:#e52715\"><strong class=\"source-bold\">のツボ</strong></span></h4>\n<blockquote><p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">スエズ運河開通</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">869</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>野<rt>8</rt></ruby><ruby>郎<rt>6</rt></ruby></strong></span>が<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>鍬<rt>9</rt><rt data-source-position=\"below\">ク<span data-source-color=\"black\" style=\"color:#001000\">ワ</span></rt></ruby></strong></span>持ち 運河掘る）<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>アメリカの<strong class=\"source-bold\">大陸横断鉄道開通と同じ年</strong>だよ</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">スエズ運河会社株の<ruby>買収<rt>ばいしゅう</rt></ruby></strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">875</strong></span>］（ディズレーリが <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>イ<rt>1</rt></ruby><ruby>ヤ<rt>8</rt></ruby><ruby>な<rt>7</rt></ruby><ruby>ゴ<rt>5</rt></ruby></strong></span>リ押し）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">ファショダ事件</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">898</strong></span>］（フランスが <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>番<rt>8</rt></ruby><ruby>悔<rt>9</rt></ruby><ruby>や<rt>8</rt></ruby></strong></span>んだ ファショダ事件）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">南アフリカ戦争<ruby>勃発<rt>ぼっぱつ</rt></ruby></strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">899</strong></span>］（<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>一<rt>1</rt></ruby><ruby>派<rt>8</rt></ruby><ruby>組<rt>9</rt></ruby></strong></span>め<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>組<rt>9</rt></ruby></strong></span>め 南アフリカ戦争）</p>\n<p><span data-source-color=\"red\" style=\"color:#e52715\">●</span><strong class=\"source-bold\">モロッコ事件</strong>［1<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">905</strong></span>／19<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">11</strong></span>］（モロッコに <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>行<rt>1</rt></ruby><ruby>く<rt>9</rt></ruby><ruby>は<rt>0</rt></ruby><ruby>強<rt>5</rt></ruby></strong></span>引 <span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>い<rt>1</rt></ruby><ruby>い<rt>1</rt></ruby></strong></span>感じ）<br><span data-source-color=\"green\" style=\"color:#315837\">➡</span>第1次［1905］、第2次［1911］をセットで覚えておこう</p></blockquote>\n<p>ヨーロッパ各国はいよいよ帝国主義の時代に突入したね。各国の対立は、最終的には第一次世界大戦に向かうことになるんだけど、その前に、次回はヨーロッパ各国の国内問題だよ。次回も<ruby>頑張<rt>がんば</rt></ruby>っていこう〜。</p>"
};

